//! Every character the generated rules text can contain must be one the app's fonts can
//! draw (a missing glyph shows as an empty box). Card text is generated by
//! `card_model::describe`; this renders it for a modal card, a token with a quoted ability,
//! a predefined token with its reminder, a keyword-cost line and every invented card, and
//! asks egui's fonts about each non-ASCII character in it.

use card_model::describe::rules_text_in;
use card_model::{
    AbilityDef, Amount, Body, CardDef, CardType, Cost, Effect, Keyword, ManaProduce, ManaType,
    Mode, PlayerRef, Timing,
};
use eframe::egui::FontId;
use egui_kittest::Harness;
use std::collections::BTreeSet;

fn mode(effect: Effect) -> Mode {
    Mode {
        targets: Vec::new(),
        effect,
        groups: Vec::new(),
    }
}

fn spell(abilities: Vec<AbilityDef>) -> CardDef {
    CardDef {
        name: "Test Card".into(),
        card_types: vec![CardType::Sorcery],
        abilities,
        ..CardDef::default()
    }
}

fn token(key: &str, types: &[CardType], subtype: &str) -> CardDef {
    CardDef {
        name: format!("{subtype} Token"),
        key: Some(key.into()),
        token: true,
        card_types: types.to_vec(),
        creature_types: vec![subtype.into()],
        ..CardDef::default()
    }
}

fn texts() -> Vec<String> {
    let draw = Effect::Draw {
        who: PlayerRef::You,
        amount: Amount::Fixed(1),
    };
    let gain = Effect::GainLife {
        who: PlayerRef::You,
        amount: Amount::Fixed(3),
    };
    let make = |key: &str| Effect::CreateToken {
        token: key.into(),
        count: Amount::Fixed(1),
        who: PlayerRef::You,
    };
    let sacrifice_for_mana = AbilityDef::Mana {
        cost: Cost {
            tap: true,
            sacrifice_self: true,
            ..Cost::default()
        },
        produce: ManaProduce::AnyColor,
        only_if: None,
        spend: None,
        then: None,
    };
    let treasure = CardDef {
        abilities: vec![sacrifice_for_mana],
        ..token("treasure", &[CardType::Artifact], "Treasure")
    };
    let spawn = CardDef {
        power: Some(0),
        toughness: Some(1),
        colors: Some(Vec::new()),
        abilities: vec![AbilityDef::Mana {
            cost: Cost {
                sacrifice_self: true,
                ..Cost::default()
            },
            produce: ManaProduce::One(ManaType::Colorless),
            only_if: None,
            spend: None,
            then: None,
        }],
        ..token("spawn", &[CardType::Creature], "Eldrazi Spawn")
    };
    let defs = [treasure, spawn];
    let lookup = |key: &str| defs.iter().find(|d| d.key.as_deref() == Some(key));
    let cycling = AbilityDef::Activated {
        cost: Cost {
            life: 2,
            discard_self: true,
            ..Cost::default()
        },
        timing: Timing::Instant,
        only_if: None,
        body: Body::Effect(mode(draw.clone())),
        from: card_model::ActivationZone::Hand,
        cycling: true,
        reduce: None,
    };
    let cards = [
        // A modal card.
        spell(vec![AbilityDef::Spell(Body::Modal {
            min: 1,
            max: 2,
            modes: vec![mode(draw.clone()), mode(gain)],
        })]),
        // Tokens: predefined with its reminder, and one with a quoted ability.
        spell(vec![AbilityDef::Spell(Body::Effect(mode(Effect::Seq(
            vec![make("treasure"), make("spawn")],
        ))))]),
        // A keyword-cost line.
        CardDef {
            keywords: vec![Keyword::Flying],
            abilities: vec![cycling],
            ..spell(Vec::new())
        },
        // A Saga's chapter ability ("IV — Draw a card.", CR 715.2a).
        spell(vec![AbilityDef::Triggered {
            when: card_model::Trigger::Chapter(4),
            intervening_if: None,
            body: Body::Effect(mode(draw.clone())),
        }]),
    ];
    let mut out: Vec<String> = cards
        .iter()
        .flat_map(|c| rules_text_in(c, &lookup))
        .collect();
    // Every invented card of the game's own catalog.
    let cat = harness::catalog();
    for def in &cat.defs {
        out.extend(rules_text_in(def, &|k| cat.find(k).map(|id| cat.get(id))));
        out.push(card_model::describe::type_line(def));
    }
    out
}

#[test]
fn rules_text_only_uses_characters_the_fonts_can_draw() {
    let texts = texts();
    let non_ascii: BTreeSet<char> = texts
        .iter()
        .flat_map(|t| t.chars())
        .filter(|c| !c.is_ascii())
        .collect();
    // The characters the generator itself writes must be among them.
    assert!(
        non_ascii.contains(&'—') && non_ascii.contains(&'•'),
        "{non_ascii:?}"
    );
    let mut h = Harness::builder().build_ui_state(
        |ui, (wanted, missing): &mut (Vec<char>, Vec<char>)| {
            let font = FontId::proportional(14.0);
            for c in wanted.iter() {
                if !ui.ctx().fonts_mut(|f| f.has_glyph(&font, *c)) {
                    missing.push(*c);
                }
            }
        },
        (non_ascii.iter().copied().collect::<Vec<_>>(), Vec::new()),
    );
    h.run();
    let missing = &h.state().1;
    assert!(
        missing.is_empty(),
        "the app's fonts cannot draw: {missing:?} (in {} generated lines)",
        texts.len()
    );
}

/// The check can fail: a character no font has is reported.
#[test]
fn the_glyph_check_notices_a_missing_character() {
    let mut h = Harness::builder().build_ui_state(
        |ui, found: &mut bool| {
            *found = ui
                .ctx()
                .fonts_mut(|f| f.has_glyph(&FontId::proportional(14.0), '\u{10FFFD}'));
        },
        true,
    );
    h.run();
    assert!(!*h.state());
}
